// Fast lookup cache
const cityBySlugMap = new Map<string, CityData>();
for (const city of cities) {
  cityBySlugMap.set(city.slug, city);
}

export function getCityBySlug(slug: string): CityData | undefined {
  return cityBySlugMap.get(slug);
}

export function getAllCitySlugs(): string[] {
  return cities.map((c) => c.slug);
}

export function getCitiesByTier(tier: 'Tier 1' | 'Tier 2' | 'Tier 3'): CityData[] {
  return cities.filter((c) => c.tier === tier);
}

export function getCitiesByState(state: string): CityData[] {
  return cities.filter((c) => c.state.toLowerCase() === state.toLowerCase());
}

export function getAllStates(): string[] {
  return Array.from(new Set(cities.map((c) => c.state))).sort();
}

